using FixFinder.Core.LocalFixes;
using FixFinder.Core.Logic;

namespace FixFinder.Tests;

/// <summary>
/// A flag a loop never sets, in TypeScript, Ruby, PHP, Lua, Perl, Dart, PowerShell, Scala, Fortran, Rust, F# and OCaml:
/// report sets found off before a loop that looks for the wanted mark and never sets it, then tests found. Left alone in
/// each: each found program put right and a flag the loop sets - with, in some, a switch set off away from any loop, and a
/// flag handed to a call that may set it, as PHP's reference and Perl's \$seen; and a JavaScript file, whose flags the
/// analysis follows.
/// </summary>
public class FlagNeverSetPatternsTests
{
    private static IReadOnlyList<LogicFinding> Scanned(string fileName, string code) =>
        LogicPatterns.Scan(new SourceFile { Path = Path.Combine(Path.GetTempPath(), fileName), Lines = code.Replace("\r\n", "\n").Split('\n') })
            .Where(finding => finding.PatternId.EndsWith("-flag-never-set", StringComparison.Ordinal))
            .ToList();

    /// <summary>The file, the program, and what the check said of it here: the finding's line, check and words.</summary>
    public static TheoryData<string, string, string> Found => new()
    {
        { "report.dart", "String report(List<int> marks, int wanted) {\n  var found = false;\n  for (var mark in marks) {\n    if (mark == wanted) {\n      print('found it');\n    }\n  }\n  if (found) {\n    return 'present';\n  }\n  return 'missing';\n}\n\nvoid main() {\n  print(report([1, 2, 3], 2));\n}\n", "8|logic-dart-flag-never-set|`found` is set to `false` on line 2 and nothing changes it - the loop on line 3 never sets it - so the test of `found` on line 8 is never true" },
        { "report.f90", "program main\n  implicit none\n  character(len=7) :: said\n  said = report([1, 2, 3], 2)\n  print *, said\ncontains\n  function report(marks, wanted) result(answer)\n    integer, intent(in) :: marks(:), wanted\n    character(len=7) :: answer\n    logical :: found\n    integer :: index\n    found = .false.\n    do index = 1, size(marks)\n      if (marks(index) == wanted) then\n        print *, \"found it\"\n      end if\n    end do\n    if (found) then\n      answer = \"present\"\n    else\n      answer = \"missing\"\n    end if\n  end function report\nend program main\n", "18|logic-fortran-flag-never-set|`found` is set to `.false.` on line 12 and nothing changes it - the loop on line 13 never sets it - so the test of `found` on line 18 is never true" },
        { "report.fsx", "let report (marks: int list) wanted =\n    let mutable found = false\n    for mark in marks do\n        if mark = wanted then\n            printfn \"found it\"\n    if found then \"present\" else \"missing\"\n\nprintfn \"%s\" (report [1; 2; 3] 2)\n", "6|logic-fsharp-flag-never-set|`found` is set to `false` on line 2 and nothing changes it - the loop on line 3 never sets it - so the test of `found` on line 6 is never true" },
        { "report.lua", "local function report(marks, wanted)\n  local found = false\n  for _, mark in ipairs(marks) do\n    if mark == wanted then\n      print(\"found it\")\n    end\n  end\n  if found then\n    return \"present\"\n  end\n  return \"missing\"\nend\n\nprint(report({1, 2, 3}, 2))\n", "8|logic-lua-flag-never-set|`found` is set to `false` on line 2 and nothing changes it - the loop on line 3 never sets it - so the test of `found` on line 8 is never true" },
        { "report.ml", "let report marks wanted =\n  let found = ref false in\n  for index = 0 to List.length marks - 1 do\n    if List.nth marks index = wanted then\n      print_endline \"found it\"\n  done;\n  if !found then \"present\" else \"missing\"\n\nlet () = print_endline (report [1; 2; 3] 2)\n", "7|logic-ocaml-flag-never-set|`found` is set to `false` on line 2 and nothing changes it - the loop on line 3 never sets it - so the test of `found` on line 7 is never true" },
        { "report.php", "<?php\nfunction report(array $marks, int $wanted): string\n{\n    $found = false;\n    foreach ($marks as $mark) {\n        if ($mark === $wanted) {\n            echo \"found it\", PHP_EOL;\n        }\n    }\n    if ($found) {\n        return \"present\";\n    }\n    return \"missing\";\n}\n\necho report([1, 2, 3], 2), PHP_EOL;\n", "10|logic-php-flag-never-set|`$found` is set to `false` on line 4 and nothing changes it - the loop on line 5 never sets it - so the test of `$found` on line 10 is never true" },
        { "report.pl", "use strict;\nuse warnings;\n\nsub report {\n    my ($wanted, @marks) = @_;\n    my $found = 0;\n    foreach my $mark (@marks) {\n        if ($mark == $wanted) {\n            print \"found it\\n\";\n        }\n    }\n    if ($found) {\n        return \"present\";\n    }\n    return \"missing\";\n}\n\nprint report(2, 1, 2, 3), \"\\n\";\n", "12|logic-perl-flag-never-set|`$found` is set to `0` on line 6 and nothing changes it - the loop on line 7 never sets it - so the test of `$found` on line 12 is never true" },
        { "report.ps1", "function Get-Report($marks, $wanted) {\n    $found = $false\n    foreach ($mark in $marks) {\n        if ($mark -eq $wanted) {\n            Write-Host \"found it\"\n        }\n    }\n    if ($found) {\n        return \"present\"\n    }\n    return \"missing\"\n}\n\nGet-Report @(1, 2, 3) 2\n", "8|logic-powershell-flag-never-set|`$found` is set to `$false` on line 2 and nothing changes it - the loop on line 3 never sets it - so the test of `$found` on line 8 is never true" },
        { "report.rb", "def report(marks, wanted)\n  found = false\n  marks.each do |mark|\n    if mark == wanted\n      puts \"found it\"\n    end\n  end\n  if found\n    return \"present\"\n  end\n  \"missing\"\nend\n\nputs report([1, 2, 3], 2)\n", "8|logic-ruby-flag-never-set|`found` is set to `false` on line 2 and nothing changes it - the loop on line 3 never sets it - so the test of `found` on line 8 is never true" },
        { "report.rs", "fn report(marks: &[i32], wanted: i32) -> &'static str {\n    let mut found = false;\n    for mark in marks {\n        if *mark == wanted {\n            println!(\"found it\");\n        }\n    }\n    if found {\n        return \"present\";\n    }\n    \"missing\"\n}\n\nfn main() {\n    println!(\"{}\", report(&[1, 2, 3], 2));\n}\n", "8|logic-rust-flag-never-set|`found` is set to `false` on line 2 and nothing changes it - the loop on line 3 never sets it - so the test of `found` on line 8 is never true" },
        { "Report.scala", "object Report {\n  def report(marks: List[Int], wanted: Int): String = {\n    var found = false\n    for (mark <- marks) {\n      if (mark == wanted) {\n        println(\"found it\")\n      }\n    }\n    if (found) {\n      return \"present\"\n    }\n    \"missing\"\n  }\n\n  def main(args: Array[String]): Unit = {\n    println(report(List(1, 2, 3), 2))\n  }\n}\n", "9|logic-scala-flag-never-set|`found` is set to `false` on line 3 and nothing changes it - the loop on line 4 never sets it - so the test of `found` on line 9 is never true" },
        { "report.ts", "function report(marks: number[], wanted: number): string {\n  let found = false;\n  for (const mark of marks) {\n    if (mark === wanted) {\n      console.log(\"found it\");\n    }\n  }\n  if (found) {\n    return \"present\";\n  }\n  return \"missing\";\n}\n\nconsole.log(report([1, 2, 3], 2));\n", "8|logic-typescript-flag-never-set|`found` is set to `false` on line 2 and nothing changes it - the loop on line 3 never sets it - so the test of `found` on line 8 is never true" },
    };

    /// <summary>The file, and a program the check must leave alone: each found program put right, and the near misses.</summary>
    public static TheoryData<string, string> NearMisses => new()
    {
        { "report.dart", "String report(List<int> marks, int wanted) {\n  var found = false;\n  for (var mark in marks) {\n    if (mark == wanted) {\n      found = true;\n    }\n  }\n  if (found) {\n    return 'present';\n  }\n  return 'missing';\n}\n\nvoid main() {\n  print(report([1, 2, 3], 2));\n}\n" },
        { "report.f90", "program main\n  implicit none\n  character(len=7) :: said\n  said = report([1, 2, 3], 2)\n  print *, said\ncontains\n  function report(marks, wanted) result(answer)\n    integer, intent(in) :: marks(:), wanted\n    character(len=7) :: answer\n    logical :: found\n    integer :: index\n    found = .false.\n    do index = 1, size(marks)\n      if (marks(index) == wanted) then\n        found = .true.\n      end if\n    end do\n    if (found) then\n      answer = \"present\"\n    else\n      answer = \"missing\"\n    end if\n  end function report\nend program main\n" },
        { "report.fsx", "let report (marks: int list) wanted =\n    let mutable found = false\n    for mark in marks do\n        if mark = wanted then\n            found <- true\n    if found then \"present\" else \"missing\"\n\nprintfn \"%s\" (report [1; 2; 3] 2)\n" },
        { "report.lua", "local function report(marks, wanted)\n  local found = false\n  for _, mark in ipairs(marks) do\n    if mark == wanted then\n      found = true\n    end\n  end\n  if found then\n    return \"present\"\n  end\n  return \"missing\"\nend\n\nprint(report({1, 2, 3}, 2))\n" },
        { "report.ml", "let report marks wanted =\n  let found = ref false in\n  for index = 0 to List.length marks - 1 do\n    if List.nth marks index = wanted then\n      found := true\n  done;\n  if !found then \"present\" else \"missing\"\n\nlet () = print_endline (report [1; 2; 3] 2)\n" },
        { "report.php", "<?php\nfunction report(array $marks, int $wanted): string\n{\n    $found = false;\n    foreach ($marks as $mark) {\n        if ($mark === $wanted) {\n            $found = true;\n        }\n    }\n    if ($found) {\n        return \"present\";\n    }\n    return \"missing\";\n}\n\necho report([1, 2, 3], 2), PHP_EOL;\n" },
        { "report.pl", "use strict;\nuse warnings;\n\nsub report {\n    my ($wanted, @marks) = @_;\n    my $found = 0;\n    foreach my $mark (@marks) {\n        if ($mark == $wanted) {\n            $found = 1;\n        }\n    }\n    if ($found) {\n        return \"present\";\n    }\n    return \"missing\";\n}\n\nprint report(2, 1, 2, 3), \"\\n\";\n" },
        { "report.ps1", "function Get-Report($marks, $wanted) {\n    $found = $false\n    foreach ($mark in $marks) {\n        if ($mark -eq $wanted) {\n            $found = $true\n        }\n    }\n    if ($found) {\n        return \"present\"\n    }\n    return \"missing\"\n}\n\nGet-Report @(1, 2, 3) 2\n" },
        { "report.rb", "def report(marks, wanted)\n  found = false\n  marks.each do |mark|\n    if mark == wanted\n      found = true\n    end\n  end\n  if found\n    return \"present\"\n  end\n  \"missing\"\nend\n\nputs report([1, 2, 3], 2)\n" },
        { "report.rs", "fn report(marks: &[i32], wanted: i32) -> &'static str {\n    let mut found = false;\n    for mark in marks {\n        if *mark == wanted {\n            found = true;\n        }\n    }\n    if found {\n        return \"present\";\n    }\n    \"missing\"\n}\n\nfn main() {\n    println!(\"{}\", report(&[1, 2, 3], 2));\n}\n" },
        { "Report.scala", "object Report {\n  def report(marks: List[Int], wanted: Int): String = {\n    var found = false\n    for (mark <- marks) {\n      if (mark == wanted) {\n        found = true\n      }\n    }\n    if (found) {\n      return \"present\"\n    }\n    \"missing\"\n  }\n\n  def main(args: Array[String]): Unit = {\n    println(report(List(1, 2, 3), 2))\n  }\n}\n" },
        { "report.ts", "function report(marks: number[], wanted: number): string {\n  let found = false;\n  for (const mark of marks) {\n    if (mark === wanted) {\n      found = true;\n    }\n  }\n  if (found) {\n    return \"present\";\n  }\n  return \"missing\";\n}\n\nconsole.log(report([1, 2, 3], 2));\n" },
        { "near.dart", "String hasNegative(List<int> marks) {\n  var negative = false;\n  for (var mark in marks) {\n    if (mark < 0) {\n      negative = true;\n    }\n  }\n  if (negative) {\n    return 'a negative mark';\n  }\n  return 'all at least 0';\n}\n\nvoid main() {\n  print(hasNegative([1, -2]));\n}\n" },
        { "near.f90", "program main\n  implicit none\n  print *, has_negative([1, -2])\ncontains\n  logical function has_negative(marks)\n    integer, intent(in) :: marks(:)\n    logical :: negative\n    integer :: index\n    negative = .false.\n    do index = 1, size(marks)\n      if (marks(index) < 0) then\n        negative = .true.\n      end if\n    end do\n    if (negative) then\n      has_negative = .true.\n    else\n      has_negative = .false.\n    end if\n  end function has_negative\nend program main\n" },
        { "near.fsx", "let hasNegative (marks: int list) =\n    let mutable negative = false\n    for mark in marks do\n        if mark < 0 then\n            negative <- true\n    if negative then \"a negative mark\" else \"all at least 0\"\n\nprintfn \"%s\" (hasNegative [1; -2])\n" },
        { "near.lua", "local function has_negative(marks)\n  local negative = false\n  for _, mark in ipairs(marks) do\n    if mark < 0 then\n      negative = true\n    end\n  end\n  if negative then\n    return \"a negative mark\"\n  end\n  return \"all at least 0\"\nend\n\nprint(has_negative({1, -2}))\n" },
        { "near.ml", "let has_negative marks =\n  let negative = ref false in\n  for index = 0 to List.length marks - 1 do\n    if List.nth marks index < 0 then\n      negative := true\n  done;\n  if !negative then \"a negative mark\" else \"all at least 0\"\n\nlet () = print_endline (has_negative [1; -2])\n" },
        { "near.php", "<?php\nfunction markSeen(bool &$seen): void\n{\n    $seen = true;\n}\n\nfunction throughReference(array $marks): string\n{\n    $seen = false;\n    foreach ($marks as $mark) {\n        if ($mark > 0) {\n            markSeen($seen);\n        }\n    }\n    if ($seen) {\n        return \"seen\";\n    }\n    return \"not seen\";\n}\n\nfunction hasNegative(array $marks): string\n{\n    $negative = false;\n    foreach ($marks as $mark) {\n        if ($mark < 0) {\n            $negative = true;\n        }\n    }\n    if ($negative) {\n        return \"a negative mark\";\n    }\n    return \"all at least 0\";\n}\n\necho throughReference([3]), \" \", hasNegative([1, -2]), PHP_EOL;\n" },
        { "near.pl", "use strict;\nuse warnings;\n\nsub mark_seen {\n    my ($seen) = @_;\n    $$seen = 1;\n}\n\nsub through_reference {\n    my @marks = @_;\n    my $seen = 0;\n    foreach my $mark (@marks) {\n        if ($mark > 0) {\n            mark_seen(\\$seen);\n        }\n    }\n    if ($seen) {\n        return \"seen\";\n    }\n    return \"not seen\";\n}\n\nsub has_negative {\n    my @marks = @_;\n    my $negative = 0;\n    foreach my $mark (@marks) {\n        if ($mark < 0) {\n            $negative = 1;\n        }\n    }\n    if ($negative) {\n        return \"a negative mark\";\n    }\n    return \"all at least 0\";\n}\n\nprint through_reference(3), \" \", has_negative(1, -2), \"\\n\";\n" },
        { "near.ps1", "function Test-Negative($marks) {\n    $negative = $false\n    foreach ($mark in $marks) {\n        if ($mark -lt 0) {\n            $negative = $true\n        }\n    }\n    if ($negative) {\n        return \"a negative mark\"\n    }\n    return \"all at least 0\"\n}\n\nTest-Negative @(1, -2)\n" },
        { "near.rb", "def negative?(marks)\n  negative = false\n  marks.each do |mark|\n    if mark < 0\n      negative = true\n    end\n  end\n  if negative\n    return true\n  end\n  false\nend\n\ndef mark_seen(marks, seen)\n  marks.each { |mark| seen[:any] = true if mark > 0 }\nend\n\ndef seen?(marks)\n  seen = false\n  marks.each do |mark|\n    if mark > 0\n      seen = true\n    end\n  end\n  seen\nend\n\np negative?([1, -2]), seen?([3])\n" },
        { "near.rs", "fn has_negative(marks: &[i32]) -> &'static str {\n    let mut negative = false;\n    for mark in marks {\n        if *mark < 0 {\n            negative = true;\n        }\n    }\n    if negative {\n        return \"a negative mark\";\n    }\n    \"all at least 0\"\n}\n\nfn main() {\n    println!(\"{}\", has_negative(&[1, -2]));\n}\n" },
        { "Near.scala", "object Near {\n  def hasNegative(marks: List[Int]): String = {\n    var negative = false\n    for (mark <- marks) {\n      if (mark < 0) {\n        negative = true\n      }\n    }\n    if (negative) {\n      return \"a negative mark\"\n    }\n    \"all at least 0\"\n  }\n\n  def main(args: Array[String]): Unit = {\n    println(hasNegative(List(1, -2)))\n  }\n}\n" },
        { "near.ts", "function hasNegative(marks: number[]): string {\n  let negative = false;\n  for (const mark of marks) {\n    if (mark < 0) {\n      negative = true;\n    }\n  }\n  if (negative) {\n    return \"a negative mark\";\n  }\n  return \"all at least 0\";\n}\n\nfunction show(marks: number[]): number {\n  let debug = false;\n  if (debug) {\n    console.log(marks);\n  }\n  return marks.length;\n}\n\nconsole.log(hasNegative([1, -2]), show([1]));\n" },
        { "report.js", "function report(marks, wanted) {\n  let found = false;\n  for (const mark of marks) {\n    if (mark === wanted) {\n      console.log(\"found it\");\n    }\n  }\n  if (found) {\n    return \"present\";\n  }\n  return \"missing\";\n}\n\nconsole.log(report([1, 2, 3], 2));\n" },
    };

    [Theory]
    [MemberData(nameof(Found))]
    public void AFlagNothingSetsIsFoundWhereItIsTested(string fileName, string code, string said)
    {
        Assert.Equal([said], Scanned(fileName, code).Select(finding => $"{finding.Line}|{finding.PatternId}|{finding.Message}"));
    }

    [Theory]
    [MemberData(nameof(NearMisses))]
    public void AFlagSomethingMaySetIsLeftAlone(string fileName, string code)
    {
        Assert.Empty(Scanned(fileName, code));
    }
}
